open Ogpu.Diagnostics
let fail s=raise(Failure s)
let ok=function Ok x->x|Result.Error e->fail(Ogpu.Error.to_string e)
let expect k=function Result.Error(e:Ogpu.Error.t)when e.kind=k->()|_->fail"expected error"
let ()=let d=Ogpu.Handle.create_device()and f=Ogpu.Handle.create_device()in let x=ok(create~device:d~message_capacity:4~trace_capacity:3~max_label_length:16~max_message_length:32)in expect Ogpu.Error.Cross_device(validate f x);expect Ogpu.Error.Invalid_state(pop_debug x);ignore(ok(push_debug x"frame"));ignore(ok(pop_debug x));ignore(ok(begin_capture x"capture"));expect Ogpu.Error.Invalid_state(begin_capture x"again");ignore(ok(end_capture x));expect Ogpu.Error.Invalid_state(end_capture x);expect Ogpu.Error.Invalid_argument(add_message x~severity:Info~category:Validation(String.make 33 'x'));for i=1 to 100000 do ignore(ok(add_message x~severity:Warning~category:Performance(string_of_int i)));ignore(ok(timestamp x~label:"gpu"(Int64.of_int i)))done;if List.length(messages x)<>4||List.length(traces x)<>3||dropped_messages x<>99996||dropped_traces x<>99997 then fail"bounded rings";let seq=List.map(fun m->m.sequence)(messages x)in if seq<>List.sort Int64.compare seq then fail"sequence order";let prepare n=List.init 50(fun i->Printf.sprintf"%08d"(n+i))in let expected=List.concat_map prepare[0;50;100;150]|>List.sort String.compare in let ws=Array.init 4(fun i->Domain.spawn(fun()->prepare(i*50)))in let got=Array.to_list ws|>List.concat_map Domain.join|>List.sort String.compare in if got<>expected then fail"domain ordering";drain_device_loss x;if messages x<>[]||traces x<>[]then fail"drain";destroy x;expect Ogpu.Error.Stale_handle(add_message x~severity:Error~category:Resource"late");print_endline"OGPU bounded diagnostics passed"
